static unsigned checks=0;
static void Check(bool v,const std::string& text){if(!v)throw std::runtime_error(text);++checks;}
static void Near(float a,float b,const char* text){Check(std::abs(a-b)<.002f,text);}
static void Same(const TransformComponent& a,const TransformComponent& b,const char* text){auto x=TransformMatrix(a),y=TransformMatrix(b);for(int i=0;i<16;++i)Near(float(x[i]),float(y[i]),text);}
static Entity Named(const World& w,const std::string& name){for(auto e:w.Entities())if(auto* t=w.GetComponent<TagComponent>(e);t&&t->name==name)return e;throw std::runtime_error("Missing entity "+name);}
static Json Ref(const World& w,Entity e){return {{"$entity",SceneSerializer::EntitySceneId(w,e)}};}
struct OwnedFile {std::filesystem::path path;~OwnedFile(){std::error_code ec;std::filesystem::remove(path,ec);}};
